{
  "method": "per_example_tost",
  "description": "Two One-Sided Tests (TOST) for equivalence of SFT vs GRPO accuracy on GSM8K (N=1319 paired examples per comparison)",
  "test_details": {
    "test_type": "paired_tost_on_binary_outcomes",
    "n_examples": 1319,
    "pairing": "same GSM8K questions evaluated under both SFT and GRPO, matched by question hash",
    "d_i_definition": "sft_correct_i - grpo_correct_i for each example i",
    "null_hypothesis": "H0_1: mean(d) >= epsilon OR H0_2: mean(d) <= -epsilon",
    "alternative": "HA: -epsilon < mean(d) < epsilon (equivalence)",
    "alpha": 0.05
  },
  "results": {
    "cka_only": {
      "sft_accuracy": 0.6391,
      "sft_source": "eval_gsm8k_sft_cka_only_20_n1319.json (westd-32935)",
