        "vs_grpo_seed42": {
          "grpo_accuracy": 0.6437,
          "grpo_source": "gsm8k_grpo_cka_only_20.json (westb-23072)",
          "mean_diff_pp": -0.45,
          "se": 0.006434,
          "ci90_pp": [-1.51, 0.60],
