          "mean_diff_pp": -0.68,
          "se": 0.006566,
          "ci90_pp": [-1.76, 0.40],
          "tost_eps1pp": {"p_tost": 0.3143, "equivalent": false},
          "tost_eps2pp": {"p_tost": 0.0225, "equivalent": true},
          "tost_eps3pp": {"p_tost": 0.000215, "equivalent": true}
        }
