      "pooled_summary": {
        "mean_diff_range_pp": [-0.68, -0.15],
        "all_equivalent_at_eps2pp": true,
        "worst_p_at_eps2pp": 0.0225
      }
    },
    "standard": {
      "sft_accuracy": 0.5921,
      "sft_source": "eval_gsm8k_sft_standard_20_n1319.json (westd-32935)",
      "comparisons": {
        "vs_grpo_seed123": {
          "grpo_accuracy": 0.5989,
          "grpo_source": "eval_gsm8k_grpo_standard_20_seed123_n1319.json",
          "mean_diff_pp": -0.68,
          "se": 0.006388,
          "ci90_pp": [-1.73, 0.37],
          "tost_eps1pp": {"p_tost": 0.3095, "equivalent": false},
          "tost_eps2pp": {"p_tost": 0.0197, "equivalent": true},
          "tost_eps3pp": {"p_tost": 0.000148, "equivalent": true}
        },
        "vs_grpo_seed456": {
          "grpo_accuracy": 0.6020,
          "grpo_source": "eval_gsm8k_grpo_standard_20_seed456_n1319.json",
          "mean_diff_pp": -0.99,
          "se": 0.006821,
          "ci90_pp": [-2.11, 0.14],
          "tost_eps1pp": {"p_tost": 0.2157, "equivalent": false},
          "tost_eps2pp": {"p_tost": 0.0686, "equivalent": false},
          "tost_eps3pp": {"p_tost": 0.0016, "equivalent": true}
        },
        "vs_grpo_fair_v2": {
          "grpo_accuracy": 0.5944,
          "grpo_source": "eval_gsm8k_grpo_standard_20_fair_v2.json",
          "mean_diff_pp": -0.23,
          "se": 0.007622,
          "ci90_pp": [-1.48, 1.03],
          "tost_eps1pp": {"p_tost": 0.1555, "equivalent": false},
          "tost_eps2pp": {"p_tost": 0.0101, "equivalent": true},
          "tost_eps3pp": {"p_tost": 0.000143, "equivalent": true}
        },
        "vs_grpo_extended_300": {
          "grpo_accuracy": 0.5929,
          "grpo_source": "eval_gsm8k_grpo_standard_20_extended_300.json",
          "mean_diff_pp": -0.08,
          "se": 0.007845,
          "ci90_pp": [-1.37, 1.21],
          "tost_eps1pp": {"p_tost": 0.1195, "equivalent": false},
          "tost_eps2pp": {"p_tost": 0.0072, "equivalent": true},
          "tost_eps3pp": {"p_tost": 0.000101, "equivalent": true}
        }
      },
      "pooled_summary": {
        "mean_diff_range_pp": [-0.99, -0.08],
        "all_equivalent_at_eps2pp": false,
        "note": "7/8 pairs equivalent at eps=2pp; std_vs_seed456 borderline (p=0.069). All 8/8 equivalent at eps=3pp.",
        "worst_p_at_eps2pp": 0.0686,
        "worst_p_at_eps3pp": 0.0016
      }
    }
  },
  "summary": {
    "claim": "SFT and GRPO produce near-identical GSM8K accuracy after structured pruning",
    "evidence": [
      "All 8 SFT-GRPO pairs have |mean_diff| < 1pp (range: 0.08pp to 0.99pp)",
      "At epsilon=2pp: 7/8 pairs statistically equivalent (p<0.05), 1 borderline (p=0.069)",
      "At epsilon=3pp: 8/8 pairs statistically equivalent (all p<0.002)",
      "90% CIs for all pairs contained within [-2.11pp, +1.21pp]",
      "GRPO consistently slightly better than SFT (all mean_diff negative), but differences trivially small"
    ],
    "recommended_epsilon": 0.02,
    "recommended_claim_text": "TOST equivalence testing (epsilon=2pp, N=1319 paired examples) confirms SFT and GRPO yield statistically equivalent GSM8K accuracy across pruning criteria (p<0.05 for 7/8 comparisons, worst p=0.069)."
  }
}

